S = input()
open_count = 0
close_count = 0
misbalance = False

if "<" in S and "=" in S:
    for char in S:
        if char == "<":
            open_count += 1
        elif char == ">":
            close_count += 1
            if close_count > open_count:
                misbalance = True
                break
    if open_count == close_count and not misbalance:
        print("Yes")
    else:
        print("No")
else:
    print("No")
